"""
title: Ask Models
author: ColeW
version: 1.0.0
description: Query cloud LLMs via Ollama proxy. Kimi (reasoning), DeepSeek (general), Qwen-VL (vision), Qwen-Coder (code), or all at once.
requirements: aiohttp
"""

import aiohttp
import asyncio
from pydantic import BaseModel, Field
from typing import Optional, Callable, Awaitable


class Tools:
    def __init__(self):
        self.valves = self.Valves()
        self.citation = False

    class Valves(BaseModel):
        ollama_url: str = Field(
            default="http://localhost:11434", description="Ollama API base URL"
        )
        timeout: int = Field(default=120, description="Request timeout in seconds")

    async def _query_ollama(self, model: str, prompt: str) -> str:
        """Internal method to query Ollama API."""
        url = f"{self.valves.ollama_url}/api/generate"
        payload = {"model": model, "prompt": prompt, "stream": False}

        try:
            timeout = aiohttp.ClientTimeout(total=self.valves.timeout)
            async with aiohttp.ClientSession(timeout=timeout) as session:
                async with session.post(url, json=payload) as resp:
                    if resp.status != 200:
                        return f"[Error: HTTP {resp.status}]"
                    data = await resp.json()
                    return data.get("response", "[No response]")
        except asyncio.TimeoutError:
            return "[Error: Request timed out]"
        except Exception as e:
            return f"[Error: {str(e)}]"

    async def ask_kimi(
        self,
        prompt: str,
        __event_emitter__: Optional[Callable[[dict], Awaitable[None]]] = None,
    ) -> str:
        """
        Query Kimi K2 Thinking model. Best for complex reasoning, analysis, and step-by-step problem solving.

        :param prompt: The question or task for the model
        :return: Model response
        """
        if __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {
                        "description": "Querying Kimi K2 Thinking...",
                        "done": False,
                    },
                }
            )

        response = await self._query_ollama("kimi-k2-thinking:cloud", prompt)

        if __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {"description": "Kimi response received", "done": True},
                }
            )

        return f"**Kimi K2 Thinking:**\n\n{response}"

    async def ask_deepseek(
        self,
        prompt: str,
        __event_emitter__: Optional[Callable[[dict], Awaitable[None]]] = None,
    ) -> str:
        """
        Query DeepSeek V3.2 model. Strong general-purpose model for diverse tasks.

        :param prompt: The question or task for the model
        :return: Model response
        """
        if __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {"description": "Querying DeepSeek V3.2...", "done": False},
                }
            )

        response = await self._query_ollama("deepseek-v3.2:cloud", prompt)

        if __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {"description": "DeepSeek response received", "done": True},
                }
            )

        return f"**DeepSeek V3.2:**\n\n{response}"

    async def ask_qwen_vl(
        self,
        prompt: str,
        __event_emitter__: Optional[Callable[[dict], Awaitable[None]]] = None,
    ) -> str:
        """
        Query Qwen3 VL 235B model. Vision-language model for image understanding and multimodal tasks.

        :param prompt: The question or task for the model
        :return: Model response
        """
        if __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {"description": "Querying Qwen3 VL...", "done": False},
                }
            )

        response = await self._query_ollama("qwen3-vl:235b-cloud", prompt)

        if __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {"description": "Qwen VL response received", "done": True},
                }
            )

        return f"**Qwen3 VL 235B:**\n\n{response}"

    async def ask_qwen_coder(
        self,
        prompt: str,
        __event_emitter__: Optional[Callable[[dict], Awaitable[None]]] = None,
    ) -> str:
        """
        Query Qwen3 Coder 480B model. Specialized for code generation, debugging, and programming tasks.

        :param prompt: The coding question or task
        :return: Model response
        """
        if __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {"description": "Querying Qwen3 Coder...", "done": False},
                }
            )

        response = await self._query_ollama("qwen3-coder:480b-cloud", prompt)

        if __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {
                        "description": "Qwen Coder response received",
                        "done": True,
                    },
                }
            )

        return f"**Qwen3 Coder 480B:**\n\n{response}"

    async def ask_all(
        self,
        prompt: str,
        __event_emitter__: Optional[Callable[[dict], Awaitable[None]]] = None,
    ) -> str:
        """
        Query ALL models in parallel and return combined responses. Use for comparing perspectives or getting diverse answers.

        :param prompt: The question or task for all models
        :return: Combined responses from all models
        """
